import sys


def is_pop_order(push_v, pop_v):
    """判断 pop_v 是否可能是 push_v 的弹出序列（题面保证 push_v 内元素互不相同）。"""
    if len(push_v) != len(pop_v):
        return False
    if sorted(push_v) != sorted(pop_v):
        return False          # 多重集不同，不可能是同一批元素的弹出顺序

    stack = []
    j = 0                     # pop_v 中下一个待匹配的弹出位置
    for value in push_v:
        stack.append(value)
        while stack and j < len(pop_v) and stack[-1] == pop_v[j]:
            stack.pop()       # 能弹就弹：晚弹会被新压入的元素永久埋住
            j += 1
    return j == len(pop_v) and not stack


def parse_seq(token):
    """把样例里的 [1,2,3,4,5] 形式解析成整数列表。"""
    token = token.strip().strip('[]')
    if not token:
        return []
    return [int(x) for x in token.replace(',', ' ').split()]


def main():
    data = ''.join(sys.stdin.read().split())
    if not data:
        return
    parts = data.split('],[')
    if len(parts) != 2:
        return
    push_v = parse_seq(parts[0])
    pop_v = parse_seq(parts[1])
    print('true' if is_pop_order(push_v, pop_v) else 'false')


if __name__ == '__main__':
    main()
